<?php session_start();require 'conectare.php';$_SESSION['id_carte']??=[];$_SESSION['nr_buc']??=[];$_SESSION['pret']??=[];$_SESSION['titlu']??=[];$_SESSION['nume_autor']??=[];$action=$_GET['actiune']??'';if($action==='adauga'){$id=filter_input(INPUT_POST,'id_carte',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare('SELECT c.id_carte,c.titlu,c.pret,a.nume_autor FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.id_carte=?');$s->execute([$id]);if($b=$s->fetch()){$found=array_search($id,array_map('intval',$_SESSION['id_carte']),true);if($found!==false)$_SESSION['nr_buc'][$found]++;else{$_SESSION['id_carte'][]=$id;$_SESSION['nr_buc'][]=1;$_SESSION['pret'][]=(float)$b['pret'];$_SESSION['titlu'][]=$b['titlu'];$_SESSION['nume_autor'][]=$b['nume_autor'];}}}if($action==='modifica'&&isset($_POST['noulnrbuc'])&&is_array($_POST['noulnrbuc']))foreach($_SESSION['id_carte'] as $i=>$_)$_SESSION['nr_buc'][$i]=max(0,(int)($_POST['noulnrbuc'][$i]??0));include 'page_top.php';include 'meniu.php';$total=0;?><h1 class="page-title">Coșul de cumpărături</h1><form action="cos.php?actiune=modifica" method="post"><div class="table-wrap"><table class="modern"><thead><tr><th>Cantitate</th><th>Carte</th><th>Preț</th><th>Total</th></tr></thead><tbody><?php $has=false;foreach($_SESSION['id_carte'] as $i=>$id):$q=(int)$_SESSION['nr_buc'][$i];if($q<=0)continue;$has=true;$line=(float)$_SESSION['pret'][$i]*$q;$total+=$line;?><tr><td><input style="width:75px" type="number" min="0" name="noulnrbuc[<?=$i?>]" value="<?=$q?>"></td><td><strong><?=h($_SESSION['titlu'][$i])?></strong><br><span class="author"><?=h($_SESSION['nume_autor'][$i])?></span></td><td><?=number_format((float)$_SESSION['pret'][$i],2,',','.')?> lei</td><td><strong><?=number_format($line,2,',','.')?> lei</strong></td></tr><?php endforeach;?><?php if(!$has):?><tr><td colspan="4">Coșul este gol.</td></tr><?php endif;?></tbody><tfoot><tr><td colspan="3"><strong>Total</strong></td><td><strong><?=number_format($total,2,',','.')?> lei</strong></td></tr></tfoot></table></div><p><input type="submit" value="Actualizează coșul"> <?php if($has):?><a class="btn" href="casa.php">Continuă spre casă</a><?php endif;?></p></form><?php include 'page_bottom.php';?>
